  digitalWrite(ledPin, HIGH);
  delay(shortFlash);
  digitalWrite(ledPin, LOW);
  delay(gap);

  digitalWrite(ledPin, HIGH);
  delay(shortFlash);
  digitalWrite(ledPin, LOW);
  delay(gap);

  digitalWrite(ledPin, HIGH);
  delay(longFlash);
  digitalWrite(ledPin, LOW);
  delay(rest);
